        template <std::size_t rake, typename InputVector, typename OutputVector>
        inline static auto
        com_constraint_error(const InputVector &com_jac_polygons, size_t n, OutputVector &out)
        {
            // input com_jac_polygons is a 3 + (3 * robot.nq) + (n * 2) where n is the number of polygons

            const size_t polygon_offset = 3 + 3 * dimension;
            // initialize x, com_constraint_grad and out
            FloatVector<rake, 4 + 3> x;
            x[0] = com_jac_polygons[0];
            x[1] = com_jac_polygons[1];
            x[2] = com_jac_polygons[2];

            FloatVector<rake, 2 * 3> com_constraint_grad;
            com_constraint_grad[0] = 0.0;
            com_constraint_grad[1] = 0.0;
            com_constraint_grad[2] = 0.0;
            com_constraint_grad[3] = 0.0;
            com_constraint_grad[4] = 0.0;
            com_constraint_grad[5] = 0.0;

            // initialize the errors to be zero
            out[2 * dimension + 0] = 0.0;
            out[2 * dimension + 1] = 0.0;

            for (size_t polygon_idx = 0; polygon_idx < n; polygon_idx++)
            {
                const auto polygon_next_idx = (polygon_idx + 1) % 4;
                x[3 + 0] = com_jac_polygons[polygon_offset + 2 * polygon_idx + 0];
                x[3 + 1] = com_jac_polygons[polygon_offset + 2 * polygon_idx + 1];
                x[3 + 2] = com_jac_polygons[polygon_offset + 2 * polygon_next_idx + 0];
                x[3 + 3] = com_jac_polygons[polygon_offset + 2 * polygon_next_idx + 1];

                std::array<FloatVector<rake, 1>, 4> v;
                std::array<FloatVector<rake, 1>, 8> y;
                v[0] = x[6] - x[4];
                v[1] = x[3] - x[5];
                v[2] = sqrt(v[0] * v[0] + v[1] * v[1]);
                v[0] = v[0] / v[2];
                v[2] = v[1] / v[2];
                v[1] = v[0] * (x[0] - x[3]) + v[2] * (x[1] - x[4]);
                v[3] = v[1] * v[0];
                v[1] = v[1] * v[2];
                v[2] = blend(0., 1., (0.) - (v[3] * v[0] + v[1] * v[2]));
                y[0] = v[3] * v[2];
                y[1] = v[1] * v[2];
                v[1] = x[6] - x[4];
                v[3] = x[3] - x[5];
                v[0] = sqrt(v[1] * v[1] + v[3] * v[3]);
                v[1] = v[1] / v[0];
                y[2] = v[1] * v[1] * v[2];
                v[0] = v[3] / v[0];
                y[3] = v[1] * v[0] * v[2];
                y[5] = v[0] * v[1] * v[2];
                y[6] = v[0] * v[0] * v[2];
                // dependent variables without operations
                y[4] = 0.;
                y[7] = 0.;

                // initialize_error
                out[2 * dimension + 0] = out[2 * dimension + 0] + y[0];
                out[2 * dimension + 1] = out[2 * dimension + 1] + y[1];

                for (size_t j = 0; j < 2 * 3; j++)
                {
                    com_constraint_grad[j] = com_constraint_grad[j] + y[2 + j];
                }
            }

            // do the actual matrix multiplication
            for (size_t dim_idx = 0; dim_idx < dimension; dim_idx++)
            {
                out[dim_idx] = com_constraint_grad[0] * com_jac_polygons[3 + dim_idx] +
                               com_constraint_grad[1] * com_jac_polygons[3 + dimension + dim_idx] +
                               com_constraint_grad[2] * com_jac_polygons[3 + 2 * dimension + dim_idx];
                out[dimension + dim_idx] =
                    com_constraint_grad[3] * com_jac_polygons[3 + dim_idx] +
                    com_constraint_grad[4] * com_jac_polygons[3 + dimension + dim_idx] +
                    com_constraint_grad[5] * com_jac_polygons[3 + 2 * dimension + dim_idx];
            }
        }

        template <std::size_t rake, typename InputVector>
        inline static auto solve_com_function_lm_inner(const InputVector &x, ConfigurationBlock<rake> &y)
        {
            std::array<FloatVector<rake, 1>, 4> v;

            v[0] = sqrt(
                1e-06 + x[0] * x[0] + x[1] * x[1] + x[2] * x[2] + x[3] * x[3] + x[4] * x[4] + x[5] * x[5] +
                x[6] * x[6] + x[7] * x[7] + x[8] * x[8] + x[9] * x[9] + x[10] * x[10] + x[11] * x[11] +
                x[12] * x[12] + x[13] * x[13]);
            v[1] = (x[14] * x[0] + x[15] * x[1] + x[16] * x[2] + x[17] * x[3] + x[18] * x[4] + x[19] * x[5] +
                    x[20] * x[6] + x[21] * x[7] + x[22] * x[8] + x[23] * x[9] + x[24] * x[10] +
                    x[25] * x[11] + x[26] * x[12] + x[27] * x[13]) /
                   v[0];
            v[2] = x[28] / v[0];
            v[3] = sqrt(
                1e-06 + x[14] * x[14] + x[15] * x[15] + x[16] * x[16] + x[17] * x[17] + x[18] * x[18] +
                x[19] * x[19] + x[20] * x[20] + x[21] * x[21] + x[22] * x[22] + x[23] * x[23] +
                x[24] * x[24] + x[25] * x[25] + x[26] * x[26] + x[27] * x[27] - v[1] * v[1]);
            v[3] = ((x[29] - v[1] * v[2]) / v[3]) / v[3];
            v[2] = (v[2] - v[1] * v[3]) / v[0];
            y[0] = x[14] * v[3] + x[0] * v[2];
            y[1] = x[15] * v[3] + x[1] * v[2];
            y[2] = x[16] * v[3] + x[2] * v[2];
            y[3] = x[17] * v[3] + x[3] * v[2];
            y[4] = x[18] * v[3] + x[4] * v[2];
            y[5] = x[19] * v[3] + x[5] * v[2];
            y[6] = x[20] * v[3] + x[6] * v[2];
            y[7] = x[21] * v[3] + x[7] * v[2];
            y[8] = x[22] * v[3] + x[8] * v[2];
            y[9] = x[23] * v[3] + x[9] * v[2];
            y[10] = x[24] * v[3] + x[10] * v[2];
            y[11] = x[25] * v[3] + x[11] * v[2];
            y[12] = x[26] * v[3] + x[12] * v[2];
            y[13] = x[27] * v[3] + x[13] * v[2];
        }

